//! The site's words: one function per Fluent message, generated by
//! `build.rs` from `locales/<lang>/site.ftl`, and what those functions need.
//! A message is called with the language first and its arguments after,
//! `words::download_title(lang)`; one with tags returns [`Piece`]s that the
//! view draws (`site::rich`).

use serde::{Deserialize, Serialize};

/// A language the site is written in.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum Lang {
    /// English, the language every message exists in first.
    En,
    /// German, addressing the reader as „du“.
    De,
}

impl Lang {
    /// Every language, in the order the language switch lists them.
    pub const ALL: [Lang; 2] = [Lang::En, Lang::De];

    /// The path prefix and `hreflang` code: `en`, `de`.
    #[must_use]
    pub const fn code(self) -> &'static str {
        match self {
            Lang::En => "en",
            Lang::De => "de",
        }
    }

    /// The language from its code, exactly as [`Lang::code`] writes it.
    #[must_use]
    pub fn from_code(code: &str) -> Option<Lang> {
        Lang::ALL.into_iter().find(|lang| lang.code() == code)
    }

    /// The language's own name, as the language switch shows it.
    #[must_use]
    pub const fn own_name(self) -> &'static str {
        match self {
            Lang::En => "English",
            Lang::De => "Deutsch",
        }
    }

    /// The `OpenGraph` locale.
    #[must_use]
    pub const fn locale(self) -> &'static str {
        match self {
            Lang::En => "en_GB",
            Lang::De => "de_DE",
        }
    }

    /// The language a browser asks for most (`Accept-Language`), among the
    /// site's; English when it names none of them.
    #[must_use]
    pub fn negotiate(accept: &str) -> Lang {
        let mut best = (0_u16, Lang::En);
        for part in accept.split(',').take(32) {
            let mut fields = part.split(';');
            let tag = fields.next().unwrap_or("").trim().to_ascii_lowercase();
            let quality = fields
                .find_map(|field| field.trim().strip_prefix("q="))
                .map_or(1000, |q| quality(q.trim()));
            let primary = tag.split('-').next().unwrap_or("");
            // Strictly greater: of equal weights the first listed wins.
            if let Some(lang) = Lang::from_code(primary)
                && quality > best.0
            {
                best = (quality, lang);
            }
        }
        best.1
    }
}

/// A quality value `0`…`1` with up to three decimals, in thousandths;
/// anything malformed counts as zero.
fn quality(value: &str) -> u16 {
    let (whole, fraction) = value.split_once('.').unwrap_or((value, ""));
    if fraction.len() > 3 || !fraction.bytes().all(|b| b.is_ascii_digit()) {
        return 0;
    }
    let digits = format!("{fraction:0<3}");
    match (whole, digits.parse::<u16>()) {
        ("1", Ok(0)) => 1000,
        ("0", Ok(thousandths)) => thousandths,
        _ => 0,
    }
}

/// CLDR's plural categories; English and German use only `One` and `Other`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Plural {
    /// Zero.
    Zero,
    /// One.
    One,
    /// Two.
    Two,
    /// Few.
    Few,
    /// Many.
    Many,
    /// Everything else.
    Other,
}

/// The plural category of `n` in `lang`.
#[must_use]
pub fn plural(lang: Lang, n: u64) -> Plural {
    match lang {
        Lang::En | Lang::De if n == 1 => Plural::One,
        Lang::En | Lang::De => Plural::Other,
    }
}

/// `n` as the language writes it: `1,234` or `1.234` (CLDR's grouping).
#[must_use]
pub fn number(lang: Lang, n: u64) -> String {
    let digits = n.to_string();
    let separator = match lang {
        Lang::En => ',',
        Lang::De => '.',
    };
    let mut out = String::new();
    for (at, digit) in digits.chars().enumerate() {
        if at > 0 && (digits.len() - at).is_multiple_of(3) {
            out.push(separator);
        }
        out.push(digit);
    }
    out
}

/// A part of a message with tags: plain text, or text inside a tag such as
/// `b` or `link`, which the view draws.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Piece {
    /// The tag around the text, if any.
    pub tag: Option<String>,
    /// The text, never markup.
    pub text: String,
}

/// An argument written into a message: text as it is, a number as the
/// language writes it.
pub trait Arg {
    /// The argument as text in `lang`.
    fn text(&self, lang: Lang) -> String;
}

impl Arg for &str {
    fn text(&self, _: Lang) -> String {
        (*self).to_owned()
    }
}

impl Arg for u64 {
    fn text(&self, lang: Lang) -> String {
        number(lang, *self)
    }
}

/// Stand-ins for `<` and `>` in an argument of a message with tags, so no
/// argument can open or close a tag; [`pieces`] gives them back.
const OPEN: char = '\u{e000}';
const CLOSE: char = '\u{e001}';

fn arg(lang: Lang, value: &impl Arg, rich: bool) -> String {
    let text = value.text(lang);
    if rich {
        text.replace('<', &OPEN.to_string())
            .replace('>', &CLOSE.to_string())
    } else {
        text
    }
}

/// A message's text cut at its tag pairs (`<name>…</name>`, one level, the
/// name lowercase letters); anything else that looks like a tag stays text.
#[must_use]
pub fn pieces(text: &str) -> Vec<Piece> {
    fn restore(text: &str) -> String {
        text.replace(OPEN, "<").replace(CLOSE, ">")
    }
    let mut out = Vec::new();
    let mut rest = text;
    let mut plain = String::new();
    while let Some(open) = rest.find('<') {
        let after = &rest[open + 1..];
        let name_end = after.find('>');
        let tagged = name_end.and_then(|end| {
            let name = &after[..end];
            if name.is_empty() || !name.bytes().all(|b| b.is_ascii_lowercase()) {
                return None;
            }
            let body = &after[end + 1..];
            let closing = format!("</{name}>");
            body.find(&closing).map(|close| {
                (
                    name.to_owned(),
                    &body[..close],
                    &body[close + closing.len()..],
                )
            })
        });
        if let Some((name, inner, tail)) = tagged {
            plain.push_str(&rest[..open]);
            if !plain.is_empty() {
                out.push(Piece {
                    tag: None,
                    text: restore(&std::mem::take(&mut plain)),
                });
            }
            out.push(Piece {
                tag: Some(name),
                text: restore(inner),
            });
            rest = tail;
        } else {
            plain.push_str(&rest[..=open]);
            rest = after;
        }
    }
    plain.push_str(rest);
    if !plain.is_empty() {
        out.push(Piece {
            tag: None,
            text: restore(&plain),
        });
    }
    out
}

include!(concat!(env!("OUT_DIR"), "/words.rs"));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn numbers_are_grouped_by_language() {
        assert_eq!(number(Lang::En, 999), "999");
        assert_eq!(number(Lang::En, 1234), "1,234");
        assert_eq!(number(Lang::De, 1234), "1.234");
        assert_eq!(number(Lang::De, 12345), "12.345");
        assert_eq!(number(Lang::En, 1_234_567), "1,234,567");
    }

    #[test]
    fn plurals() {
        assert_eq!(plural(Lang::En, 1), Plural::One);
        assert_eq!(plural(Lang::De, 0), Plural::Other);
        assert_eq!(plural(Lang::De, 2), Plural::Other);
    }

    #[test]
    fn tags_are_cut_and_arguments_cannot_open_one() {
        let text = format!(
            "Read {}<b>now</b> and <x>",
            arg(Lang::En, &"<b>evil</b>", true)
        );
        let got = pieces(&text);
        assert_eq!(
            got,
            vec![
                Piece {
                    tag: None,
                    text: "Read <b>evil</b>".into()
                },
                Piece {
                    tag: Some("b".into()),
                    text: "now".into()
                },
                Piece {
                    tag: None,
                    text: " and <x>".into()
                },
            ]
        );
    }

    #[test]
    fn accept_language() {
        assert_eq!(Lang::negotiate("de-DE,de;q=0.9,en;q=0.8"), Lang::De);
        assert_eq!(Lang::negotiate("fr-FR, en;q=0.5, de;q=0.7"), Lang::De);
        assert_eq!(Lang::negotiate("fr"), Lang::En);
        assert_eq!(Lang::negotiate(""), Lang::En);
        assert_eq!(Lang::negotiate("de;q=0, en;q=0.1"), Lang::En);
        assert_eq!(Lang::negotiate("en, de"), Lang::En);
    }
}
